        return max(h, w), {}

    def fill_slots(p, slots):
        if not slots:
            return [0] * p
        result = []
        for k in range(p):
            if k in slots:
                result.append(slots[k])
            else:
                # Continue the pattern from the nearest preceding known phase.
                for d in range(1, p + 1):
                    prev = (k - d) % p
                    if prev in slots:
                        result.append(slots[prev])
                        break
        return result

